import streamlit as st
import sqlite3
import pandas as pd

st.set_page_config(page_title="Yottaflex Pipeline Dashboard", layout="wide")

st.title("🚀 Incremental Data Engineering Pipeline Dashboard")
st.markdown("### Yottaflex AI Technologies - Take-Home Project Evaluation View")

# Connect to SQLite database generated by pipeline
conn = sqlite3.connect("analytics.db")

# Top metrics row
col1, col2, col3 = st.columns(3)

try:
    df_raw = pd.read_sql("SELECT COUNT(*) as cnt FROM transactions_raw", conn)
    valid_count = df_raw['cnt'].iloc[0]
except:
    valid_count = 0

try:
    df_q = pd.read_sql("SELECT COUNT(*) as cnt FROM quarantine_records", conn)
    quarantine_count = df_q['cnt'].iloc[0]
except:
    quarantine_count = 0

col1.metric("Successfully Processed Rows", valid_count)
col2.metric("Quarantined (Bad Data) Rows", quarantine_count)
col3.metric("Pipeline Status", "Healthy ✅")

st.markdown("---")

# Daily Customer Metrics Table
st.subheader("📊 Stateful Daily Customer Metrics")
try:
    df_metrics = pd.read_sql("SELECT * FROM daily_customer_metrics ORDER BY metric_date DESC", conn)
    st.dataframe(df_metrics, use_container_width=True)
except Exception as e:
    st.info("Run `python main.py` first to populate database metrics.")

# Quarantine Records Table
st.markdown("---")
st.subheader("🚨 Quarantine Records (Validation Errors Isolation)")
try:
    df_quarantine = pd.read_sql("SELECT * FROM quarantine_records", conn)
    st.dataframe(df_quarantine, use_container_width=True)
except:
    st.write("No quarantine records found.")